class Solution:
    def letterCombinations(self, digits: str) -> List[str]:
        hmap = {
            "2": "abc",
            "3": "def",
            "4": "ghi",
            "5": "jkl",
            "6": "mno",
            "7": "pqrs",
            "8": "tuv",
            "9": "wxyz",
        }

        ans = []
        path = []

        def choose(start: int) -> None:
            if len(path) > len(digits):
                return

            if len(path) == len(digits):
                ans.append("".join(path))
                return

            for i in range(start, len(digits)):
                for letter in hmap[digits[i]]:
                    path.append(letter)
                    choose(i + 1)
                    path.pop()

        choose(0)
        return ans
